// waves

const config = {
	vol: 0, // [-Infinity, 0]
	gain: 0.875, // [0, 1]
	adsr: {
		// all values in seconds
		attack: 1.5,
		decay: 0.0,
		sustain: 1.0,
		release: 4.0,
		// "linear" "exponential" "sine" "cosine" "bounce" "ripple" "step"
		attackCurve: "linear",
		releaseCurve: "linear"
	}
};

const audio = {
	bg: {
		src: undefined,
		lfo: undefined,
		filter: undefined,
	},
	fg: {
		src: undefined,
		amp: undefined,
		frq: undefined,
		filter: undefined,
	},
};

function initAudio() {
	Tone.Destination.volume.value = -Infinity;
	Tone.Destination.output.set({ gain: config.gain });
}

function createAudioNodes() {
	// background noise
	audio.bg.filter = new Tone.Filter({
		type: 'lowpass'
	}).toDestination();

	audio.bg.lfo = new Tone.LFO({
		type: 'sine',	// square, sawtooth, triangle, sine
		frequency: 0.1, // [0.1, 10] Hz
		min: 440,
		max: 880 
	}).connect(audio.bg.filter.frequency);

	audio.bg.src = new Tone.Noise({
		type: 'brown',
		volume: -18,
	}).connect(audio.bg.filter);

	// Foregorund
	audio.fg.amp = new Tone.AmplitudeEnvelope({
		...config.adsr,
	}).toDestination();

	audio.fg.filter = new Tone.Filter({
		type: 'lowpass',
		// frqEnv controls frequency
	}).connect(audio.fg.amp);

	audio.fg.frq = new Tone.FrequencyEnvelope({
		...config.adsr,
		attackCurve: "exponential",
		attack: 0.75 * config.adsr.attack,
		release: 1.5 * config.adsr.release,
		baseFrequency: 880,
		octaves: 4,
		// src is noise
	}).connect(audio.fg.filter.frequency);

	audio.fg.src = new Tone.Noise({
		type: 'brown',
		volume: 0,
	}).connect(audio.fg.filter);
}

function initAudioNodes() {
	// do this to make chrome stop complaining!
	audio.bg.lfo.start();
	audio.bg.src.start();
	audio.fg.src.start();
}

function scheduleRandom(time) {
	// 	randomise attack
	audio.fg.amp.set({
		attack: 2 + Math.random(),
		release: 3 + 2 * Math.random(),
	});
	audio.fg.frq.set({
		attack: 0.75 * audio.fg.amp.attack,
		release: 1.5 * audio.fg.amp.release,
	});

	// values smaller than 1 make the sound quieter
	// bc the envelope can't reach it's attack peak
	const duration = 1.0; // -> sustain duration
	const nextTime = audio.fg.amp.attack + audio.fg.amp.release + duration; // envelope duration
	const velo = 0.5 + 0.5 * Math.random(); // add dynamic

	audio.fg.amp.triggerAttackRelease(duration, time, velo);
	audio.fg.frq.triggerAttackRelease(duration, time, velo);

	// current time + the duration in seconds
	// of the triggered wave
	Tone.Transport.schedule(scheduleRandom, `+${nextTime}`);
}

