document.body.style.backgroundColor = 'hsl(0, 0%, 8%)';

(async() => {
	await Tone;
	initAudio();
	createAudioNodes();
})();

const pgs = {
	bg: undefined,
	fg: undefined,
};

const horizon = {
	height: undefined,
	value: 0.4 + 0.4 * Math.random(),
};

////////////////////////////////////////////////////// SETUP

function setup() {
	const {w, h} = getDimensions();

	createCanvas(w, h);
	pixelDensity(1);
	// noLoop() removed for animation

	horizon.height = horizon.value * height;
	pgs.bg = createBackground();
	pgs.fg = createForeground();

	noStroke();
	image(pgs.bg, 0, 0);
	image(pgs.fg, 0, horizon.height);
}

function windowResized() {
	const {w, h} = getDimensions();
	resizeCanvas(w, h);
	pg = createBackground(w, h);
}

function getDimensions() {
	const h = 0.9 * Math.max(windowWidth, windowHeight);
	const w = 0.6 * h;
	return { w, h };
}

function createBackground() {
	const sky = {
		stops: [0, 0.875, 1],
		colors: ['#0275f2', '#11a8ed', '#288fde'],
	}

	const water = {
		stops: [0, 0.125, 0.375, 0.625, 1],
		colors: ['#035fc2', '#0199c8', '#71bcd3', '#d7cbb3', '#f1e1d1']
	}

	const tmp = createGraphics(width, height);
	const ctx = tmp.drawingContext;
	const gradient = ctx.createLinearGradient(0, 0, 0, height);

	tmp.pixelDensity(1);

	for (const [i, s] of sky.stops.entries()) {
		gradient.addColorStop(s * horizon.value, sky.colors[i]);
	}

	for (const [i, s] of water.stops.entries()) {
		gradient.addColorStop(horizon.value + s * (1 - horizon.value), water.colors[i]);
	}

	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);
	return tmp;
}

function createForeground() {
	return createGraphics(width, height - horizon.height).pixelDensity(1);
}

////////////////////////////////////////////////////// DRAW

let stp = 0;

function draw() {
	let wdt = 8;
	let hgt = 1;
	let spd = audio.fg.amp.value;

	pgs.fg.clear();
	pgs.fg.noStroke();

	for (let y = 0; y < pgs.fg.height; y += hgt) {
		// [horizon: 0, beach: 1]
		const m = y / pgs.fg.height; 
		// fade waves alpha near horizon and beach
		const a = smootherStep(m, -0.1, 0.2) - smootherStep(m, 0.4 + 0.4 * spd, 0.6 + 0.6 * spd);

		// increase the size of the drawn rects to add some depth
		hgt += 0.5;
		// noise z
		stp += 0.000125;

		// gnaaa
		for (let x = 0; x < pgs.fg.width; x += wdt) {
			const n = noise(x * 0.005, y * 0.05 - stp, stp * 0.5);
			pgs.fg.fill(255, 255 * a * n**2);
			pgs.fg.rect(x, y, wdt, hgt);
		}
	}

	image(pgs.bg, 0, 0);
	image(pgs.fg, 0, horizon.height);
}

function smootherStep(n, e0 = 0, e1 = 1) {
	t = constrain((n - e0) / (e1 - e0), 0.0, 1.0);
	return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

////////////////////////////////////////////////////// USER

const fadeDuration = 2; // seconds
let isFading = false;
let initialised = false; // on user input

// fade in fade out user stuff
async function onUserAction() {
	// disallow user input while fading
	if (isFading) return;

	if (!initialised) {
		initialised = true;
		await Tone.start();

		// wait for user input
		initAudioNodes();
	}

	if (Tone.Transport.state !== 'started') {
		isFading = true;
		loop();

		Tone.Transport.start('+0.2');
		Tone.Destination.volume.linearRampTo(config.vol, fadeDuration);

		// schedule fade callback
		setTimeout(() => isFading = false, fadeDuration * 1000);

		// randomly schedule envelope
		setTimeout(() => scheduleRandom('+0.1'), fadeDuration * 1000 + Math.random() * 1000 + 2000);
	}
	else {
		isFading = true;

		Tone.Transport.stop(`+${fadeDuration}`);
		Tone.Destination.volume.linearRampTo(-Infinity, fadeDuration);

		// schedule fade callback
		setTimeout(() => {
			isFading = false
			// noLoop() removed for animation
		}, fadeDuration * 1000);
	}
}

window.mouseReleased = onUserAction;
window.touchEnded = onUserAction;

